internal static class GrammarSeedData
{
    // Fixed Snowflake millisecond/generator shared with Japanese seed; reserved offsets 3500..3577.
    // Explicit keys must remain stable when adding or reordering content.
    private const long SeedBase = FoundationSeedData.JapaneseId + 3500;
    private static readonly DateTimeOffset PublishedAt = new(2026, 11, 5, 0, 0, 0, TimeSpan.Zero);

    private const long ExpansionBase = FoundationSeedData.ExpansionId + 2000;
    private static readonly (int Key, string Code, string NativeName, string Pattern, string VietnameseName,
        string EnglishName, string VietnameseExplanation, string EnglishExplanation, string VietnameseNote,
        string EnglishNote)[] AdditionalPoints =
    [
        (0, "i-adjectives", "イ形容詞の肯定", "イ形容詞です", "Tính từ đuôi い", "Affirmative i-adjectives", "Giữ đuôi い và thêm です để miêu tả lịch sự. この本はおもしろいです。 nghĩa là Quyển sách này thú vị.", "Keep the final い and add です for a polite description. この本はおもしろいです。 means This book is interesting.", "Một số từ như きれい kết thúc bằng âm i nhưng thuộc nhóm tính từ な.", "Some words ending in the sound i, such as きれい, are na-adjectives."),
        (1, "i-adjective-negation", "イ形容詞の否定", "イ形容詞の語幹 + くないです", "Phủ định tính từ い", "Negative i-adjectives", "Bỏ い cuối rồi thêm くないです. この部屋は寒くないです。 nghĩa là Phòng này không lạnh.", "Replace the final い with くないです. この部屋は寒くないです。 means This room is not cold.", "いい đổi thành よくないです. Cũng có thể dùng くありません.", "いい becomes よくないです. The form くありません is another polite option."),
        (2, "i-adjective-past", "イ形容詞の過去", "イ形容詞の語幹 + かったです／くなかったです", "Quá khứ của tính từ い", "Past i-adjectives", "Thay い bằng かったです khi khẳng định quá khứ, hoặc くなかったです khi phủ định. 昨日は寒かったです。 nghĩa là Hôm qua trời lạnh.", "Replace the final い with かったです for the affirmative past, or くなかったです for the negative past. 昨日は寒かったです。 means It was cold yesterday.", "いい dùng gốc よ, như よかったです và よくなかったです.", "いい uses the stem よ, as in よかったです and よくなかったです."),
        (3, "na-adjectives", "ナ形容詞の使い方", "ナ形容詞です／ナ形容詞な N", "Tính từ な", "Na-adjectives", "Thêm です khi kết thúc câu và な khi bổ nghĩa danh từ. 静かな部屋です。 nghĩa là Đây là một căn phòng yên tĩnh.", "Use です at the end of a sentence and な before a modified noun. 静かな部屋です。 means It is a quiet room.", "Không thêm な ngay trước です. Phủ định có thể dùng ではありません.", "Do not insert な directly before です. A polite negative uses ではありません."),
        (4, "adjective-noun", "形容詞で名詞を修飾する", "イ形容詞 + N／ナ形容詞な N", "Miêu tả danh từ", "Modifying nouns with adjectives", "Đặt tính từ trước danh từ. 新しい車 và 便利な店 lần lượt nghĩa là xe mới và cửa hàng tiện lợi.", "Put the adjective before the noun. 新しい車 means a new car, and 便利な店 means a convenient shop.", "Tính từ い giữ い, còn tính từ な cần な trong dạng khẳng định hiện tại.", "An i-adjective retains い, while a na-adjective takes な in an affirmative non-past modifier."),
        (5, "likes-dislikes", "好き・嫌い", "N が好きです／嫌いです", "Thích và không thích", "Likes and dislikes", "Dùng が để đánh dấu đối tượng được thích hoặc không thích. 猫が好きです。 nghĩa là Tôi thích mèo.", "Use が to mark what someone likes or dislikes. 猫が好きです。 means I like cats.", "好き và 嫌い thuộc nhóm tính từ な. Chủ thể có thể được nêu bằng は khi cần.", "好き and 嫌い are na-adjectives. A topic marked with は can identify whose preference is described."),
        (6, "want-noun", "欲しい", "N が欲しいです", "Muốn có một thứ gì", "Wanting something", "Dùng 欲しい để nói mong muốn có một vật. 新しいかばんが欲しいです。 nghĩa là Tôi muốn một chiếc túi mới.", "Use 欲しい for wanting an object. 新しいかばんが欲しいです。 means I want a new bag.", "Trong câu khẳng định thông thường, mẫu này diễn đạt mong muốn của người nói. Có thể hỏi mong muốn của người nghe.", "In a normal affirmative statement this describes the speaker's desire. It can also ask about the listener's desire."),
        (7, "want-action", "希望のたい", "Vますの語幹 + たいです", "Muốn làm gì", "Wanting to do something", "Bỏ ます khỏi dạng lịch sự rồi thêm たいです. 日本語を勉強したいです。 nghĩa là Tôi muốn học tiếng Nhật.", "Remove ます from the polite verb form and add たいです. 日本語を勉強したいです。 means I want to study Japanese.", "たい chia như tính từ い. Với mong muốn của người thứ ba cần ngữ cảnh hoặc cách diễn đạt phù hợp.", "たい inflects like an i-adjective. Statements about another person's desire require suitable context or wording."),
        (8, "destination-ni-e", "移動の目的地", "場所 に／へ 行きます・来ます・帰ります", "Đích đến", "Destinations", "Dùng に hoặc へ sau địa điểm đích của động từ di chuyển. 学校に行きます。 nghĩa là Tôi đi đến trường.", "Use に or へ after the destination of a movement verb. 学校に行きます。 means I go to school.", "へ khi là trợ từ được đọc là e. Đây là cách dùng chỉ đích, khác cách dùng に chỉ thời điểm.", "The particle へ is read e. This destination use of に differs from its time use."),
        (9, "transport-de", "移動の手段", "乗り物 で 行きます", "Phương tiện di chuyển", "Transport with de", "Dùng で sau phương tiện di chuyển. バスで会社に行きます。 nghĩa là Tôi đi xe buýt đến công ty.", "Mark a means of transport with で. バスで会社に行きます。 means I go to work by bus.", "Đi bộ thường nói 歩いて行きます.", "For going on foot, the usual expression is 歩いて行きます."),
        (10, "companion-to", "一緒に行動する相手", "人 と Vます", "Làm cùng ai", "Doing something with someone", "Dùng と sau người cùng thực hiện hành động. 友達と映画を見ます。 nghĩa là Tôi xem phim cùng bạn.", "Use と after a person who takes part in an action with someone. 友達と映画を見ます。 means I watch a film with a friend.", "一人で diễn đạt làm một mình.", "一人で expresses doing something alone."),
        (11, "from-until", "起点と終点", "N から N まで", "Từ và đến", "From and until", "から chỉ điểm bắt đầu, まで chỉ điểm kết thúc trong thời gian hoặc không gian. 九時から五時まで働きます。 nghĩa là Tôi làm việc từ chín giờ đến năm giờ.", "から marks a starting point and まで an endpoint in time or space. 九時から五時まで働きます。 means I work from nine to five.", "Có thể dùng riêng から hoặc まで khi chỉ cần nêu một mốc.", "Either particle can be used on its own when only one boundary is relevant."),
        (12, "frequency", "頻度の表し方", "いつも／よく／時々／あまり／全然 + V", "Tần suất", "Frequency", "Đặt trạng từ tần suất trong câu để diễn đạt mức độ thường xuyên. 時々コーヒーを飲みます。 nghĩa là Tôi thỉnh thoảng uống cà phê.", "Use frequency adverbs to describe how often an action occurs. 時々コーヒーを飲みます。 means I sometimes drink coffee.", "Ở cách dùng nhập môn, あまり và 全然 đi với phủ định, như あまり飲みません.", "In introductory usage, あまり and 全然 accompany a negative, as in あまり飲みません."),
        (13, "invitations", "勧誘のませんか・ましょう", "Vませんか／Vましょう", "Mời và rủ cùng làm", "Invitations and suggestions", "Dùng Vませんか để mời, Vましょう để đề nghị cùng làm. 一緒に昼ご飯を食べませんか。 nghĩa là Bạn có muốn ăn trưa cùng không?", "Use Vませんか to invite and Vましょう to suggest doing something together. 一緒に昼ご飯を食べませんか。 means Would you like to have lunch together?", "ませんか ở đây là lời mời lịch sự. Có thể trả lời bằng いいですね rồi dùng ましょう.", "Here ませんか is a polite invitation. A positive response can use いいですね followed by ましょう."),
        (14, "verb-te-form", "動詞のテ形", "Vて／Vで", "Cách tạo thể て", "Forming the te-form", "Nhóm 2 bỏ る rồi thêm て. Nhóm 1 đổi đuôi theo nhóm âm, như 読む thành 読んで và 書く thành 書いて. する thành して, 来る thành 来て（きて）.", "For group 2 verbs replace る with て. Group 1 endings change by sound group, as in 読む to 読んで and 書く to 書いて. する becomes して and 来る becomes 来て（きて）.", "Nhóm 1 có う・つ・る → って, む・ぶ・ぬ → んで, く → いて, ぐ → いで, す → して. 行く là ngoại lệ 行って. Nhóm động từ phải được học cùng từ.", "Group 1 uses う・つ・る → って, む・ぶ・ぬ → んで, く → いて, ぐ → いで and す → して. 行く is the exception 行って. Learn each verb's group with the word."),
        (15, "requests-te-kudasai", "依頼のてください", "Vて + ください", "Nhờ hoặc yêu cầu làm gì", "Requests with te kudasai", "Nối thể て với ください để yêu cầu hoặc hướng dẫn. ここに名前を書いてください。 nghĩa là Hãy viết tên vào đây.", "Add ください to the te-form for a request or instruction. ここに名前を書いてください。 means Please write your name here.", "Với người có vai vế cao hoặc tình huống cần trang trọng hơn, cần chọn cách nhờ phù hợp.", "Choose a more suitable request form when hierarchy or formality requires it."),
        (16, "actions-in-progress", "進行のています", "Vて + います", "Hành động đang diễn ra", "Actions in progress", "Dùng ています để nói hành động đang diễn ra. 今、本を読んでいます。 nghĩa là Bây giờ tôi đang đọc sách.", "Use ています for an action in progress. 今、本を読んでいます。 means I am reading a book now.", "Ý nghĩa tùy động từ. Với một số động từ, ています thể hiện trạng thái kết quả, như 結婚しています.", "The interpretation depends on the verb. Some verbs use ています for a resulting state, as in 結婚しています."),
        (17, "permission", "許可のてもいいです", "Vて + もいいです", "Xin phép và cho phép", "Asking and giving permission", "Dùng てもいいです để nói được phép và thêm か để xin phép. ここに座ってもいいですか。 nghĩa là Tôi ngồi đây được không?", "Use てもいいです for permission and add か to ask for it. ここに座ってもいいですか。 means May I sit here?", "Khi từ chối, cần chọn cách nói phù hợp với quan hệ và tình huống.", "Choose a contextually appropriate expression when refusing permission."),
        (18, "prohibition", "禁止のてはいけません", "Vて + はいけません", "Điều cấm", "Prohibitions", "Dùng てはいけません để nêu điều không được làm. ここで写真を撮ってはいけません。 nghĩa là Không được chụp ảnh ở đây.", "Use てはいけません to state a prohibition. ここで写真を撮ってはいけません。 means You must not take photographs here.", "Mẫu này khá trực tiếp, thường dùng để giải thích nội quy hoặc quy định.", "This is a direct expression often used for rules and regulations."),
        (19, "sequence-te", "動作をつなぐテ形", "Vて、Vます", "Nối các hành động", "Sequencing actions", "Dùng thể て để nối các hành động theo ngữ cảnh. 朝ご飯を食べて、学校に行きます。 nghĩa là Tôi ăn sáng rồi đi học.", "Use the te-form to connect actions in context. 朝ご飯を食べて、学校に行きます。 means I eat breakfast and then go to school.", "Động từ cuối quyết định mức lịch sự và thời của toàn chuỗi.", "The final verb determines the politeness and tense of the sequence."),
        (20, "verb-nai-form", "動詞のナイ形", "Vない", "Thể phủ định ない", "Forming the nai-form", "Nhóm 2 bỏ る và thêm ない. Nhóm 1 đổi âm u cuối sang hàng a rồi thêm ない, như 書く thành 書かない. する thành しない, 来る thành 来ない（こない）.", "For group 2 replace る with ない. For group 1 change the final u sound to its a-row counterpart and add ない, as in 書く to 書かない. する becomes しない and 来る becomes 来ない（こない）.", "Động từ nhóm 1 tận cùng う đổi thành わない, như 買う → 買わない. ある phủ định là ない.", "Group 1 verbs ending in う take わない, as in 買う → 買わない. The negative of ある is ない."),
        (21, "negative-requests", "しないでください", "Vないで + ください", "Yêu cầu đừng làm gì", "Asking someone not to do something", "Dùng thể ない rồi thêm でください để yêu cầu đừng làm. ここで走らないでください。 nghĩa là Xin đừng chạy ở đây.", "Add でください to the nai-form to ask someone not to act. ここで走らないでください。 means Please do not run here.", "Đây là mẫu yêu cầu phủ định. Tránh nhầm với なくて dùng trong những cấu trúc nối khác.", "This is a negative request. Distinguish ないで from なくて in other linking structures."),
        (22, "obligation", "義務のなければなりません", "Vなければなりません", "Phải làm gì", "Obligation", "Thay ない bằng なければなりません để diễn đạt nghĩa vụ. 薬を飲まなければなりません。 nghĩa là Tôi phải uống thuốc.", "Replace ない with なければなりません to express an obligation. 薬を飲まなければなりません。 means I must take medicine.", "Trong hội thoại còn gặp ないといけません và những dạng rút gọn tùy mức lịch sự.", "Conversation also uses ないといけません and contractions depending on the register."),
        (23, "no-obligation", "必要がないこと", "Vなくてもいいです", "Không cần phải làm gì", "Lack of obligation", "Thay ない bằng なくてもいいです để nói không cần làm. 明日は来なくてもいいです。 nghĩa là Ngày mai bạn không cần đến.", "Replace ない with なくてもいいです to say an action is unnecessary. 明日は来なくてもいいです。 means You do not have to come tomorrow.", "Mẫu này bỏ yêu cầu thực hiện hành động, không diễn đạt điều cấm.", "This removes the obligation to act. A prohibition requires a different expression."),
        (24, "ability-koto-ga-dekiru", "能力・可能のことができます", "V辞書形 + ことができます", "Có thể làm gì", "Ability with koto ga dekimasu", "Dùng dạng từ điển trước ことができます để diễn đạt khả năng hoặc điều có thể làm. 日本語を読むことができます。 nghĩa là Tôi có thể đọc tiếng Nhật.", "Place the dictionary form before ことができます to express ability or possibility. 日本語を読むことができます。 means I can read Japanese.", "Danh từ chỉ hoạt động cũng có thể đi với ができます, như 料理ができます.", "An activity noun can also precede ができます, as in 料理ができます."),
        (25, "before-after", "前に・後で", "V辞書形 + 前に／Vた + 後で", "Trước và sau hành động", "Before and after an action", "Dùng dạng từ điển trước 前に và thể た trước 後で. 寝る前に、本を読みます。 nghĩa là Tôi đọc sách trước khi ngủ.", "Use the dictionary form before 前に and the ta-form before 後で. 寝る前に、本を読みます。 means I read a book before going to bed.", "Với danh từ thường dùng Nの前に và Nの後で. Thể trước 前に không đổi theo thời của động từ cuối.", "With nouns use Nの前に and Nの後で. The form before 前に stays in the dictionary form even when the final verb is past."),
        (26, "verb-ta-form", "動詞のタ形", "Vた／Vだ", "Thể quá khứ ngắn た", "Forming the ta-form", "Dùng cùng quy tắc biến đổi âm như thể て nhưng đổi て thành た và で thành だ. 書く → 書いた, 読む → 読んだ, 食べる → 食べた.", "Apply the te-form sound changes, replacing て with た and で with だ. Examples include 書く → 書いた, 読む → 読んだ and 食べる → 食べた.", "する → した, 来る → 来た（きた）, 行く → 行った. Dạng này còn xuất hiện trong các cấu trúc ngoài câu quá khứ độc lập.", "する → した, 来る → 来た（きた） and 行く → 行った. The form also appears inside structures other than independent past statements."),
        (27, "experience", "経験のたことがあります", "Vた + ことがあります", "Đã từng làm gì", "Past experience", "Dùng thể た trước ことがあります để nói về trải nghiệm đã có. 日本に行ったことがあります。 nghĩa là Tôi đã từng đến Nhật Bản.", "Use the ta-form before ことがあります to describe a past experience. 日本に行ったことがあります。 means I have been to Japan.", "Để kể một sự kiện tại thời điểm quá khứ cụ thể, thường dùng câu quá khứ thông thường.", "Use an ordinary past statement when reporting a specific event at a particular past time."),
        (28, "listing-tari", "例を挙げるたり", "Vたり、Vたりします", "Liệt kê vài hoạt động", "Listing example activities", "Thêm り vào thể た để liệt kê vài hoạt động tiêu biểu. 休みの日は本を読んだり、映画を見たりします。 nghĩa là Ngày nghỉ tôi đọc sách, xem phim và làm những việc tương tự.", "Add り to the ta-form to list representative activities. 休みの日は本を読んだり、映画を見たりします。 means On days off I do things such as reading and watching films.", "Danh sách có tính ví dụ. Động từ する ở cuối chia theo thời và mức lịch sự cần dùng.", "The list is illustrative. Inflect the final する for the required tense and politeness."),
        (29, "reason-kara", "理由のから", "普通形／丁寧形 + から", "Nêu lý do với から", "Reasons with kara", "Đặt lý do trước から. 今日は忙しいですから、行きません。 nghĩa là Vì hôm nay bận nên tôi không đi.", "Put the reason before から. 今日は忙しいですから、行きません。 means I am not going because I am busy today.", "Với danh từ và tính từ な ở dạng ngắn khẳng định hiện tại, dùng だから, như 休みだから.", "In the affirmative non-past plain form, nouns and na-adjectives use だから, as in 休みだから."),
        (30, "contrast-ga", "逆接のが", "文 が、文", "Nối hai ý tương phản", "Contrasting clauses with ga", "Dùng が để nối hai mệnh đề có ý tương phản. この店は安いですが、おいしいです。 nghĩa là Quán này rẻ mà ngon.", "Use が to connect contrasting clauses. この店は安いですが、おいしいです。 means This restaurant is inexpensive but good.", "が cũng có thể làm lời dẫn mềm trước một yêu cầu. Ở đây học cách dùng tương phản.", "が can also introduce a request gently. This point focuses on contrast."),
        (31, "comparison-yori", "比較のより", "N1 は N2 より形容詞です", "So sánh hai đối tượng", "Comparing two things", "Đặt đối tượng làm mốc trước より. 電車はバスより速いです。 nghĩa là Tàu điện nhanh hơn xe buýt.", "Put the comparison baseline before より. 電車はバスより速いです。 means The train is faster than the bus.", "Có thể hỏi bằng N1とN2と、どちらが…ですか. Câu trả lời có thể dùng Nのほうが…です.", "A question can use N1とN2と、どちらが…ですか. An answer can use Nのほうが…です."),
        (32, "superlative", "一番の比較", "範囲 で N が一番形容詞です", "Nhất trong một phạm vi", "Superlatives within a group", "Nêu phạm vi bằng で, rồi dùng 一番 trước tính từ. この中で、この本が一番おもしろいです。 nghĩa là Trong số này, quyển sách này thú vị nhất.", "Mark a comparison group with で and place 一番 before the adjective. この中で、この本が一番おもしろいです。 means Of these, this book is the most interesting.", "Cần có phạm vi so sánh rõ từ câu hoặc ngữ cảnh.", "The comparison group should be clear from the sentence or context."),
        (33, "quantity-counters", "数と助数詞", "数 + 助数詞", "Số lượng và lượng từ", "Numbers and counters", "Dùng lượng từ phù hợp với vật được đếm. りんごを三つ買います。 nghĩa là Tôi mua ba quả táo. 本を二冊読みます。 nghĩa là Tôi đọc hai quyển sách.", "Choose a counter suited to the item. りんごを三つ買います。 means I buy three apples. 本を二冊読みます。 means I read two books.", "つ, 人, 枚, 冊 và 本 có cách dùng và biến âm riêng. Học cách đọc cùng ví dụ, như 一人（ひとり） và 三本（さんぼん）.", "Counters such as つ, 人, 枚, 冊 and 本 have specific uses and sound changes. Learn readings in examples, such as 一人（ひとり） and 三本（さんぼん）."),
        (34, "purpose-ni", "移動の目的", "Vますの語幹 + に行きます", "Đi để làm gì", "Going somewhere for a purpose", "Bỏ ます rồi dùng に trước động từ di chuyển để nêu mục đích. 本を買いに行きます。 nghĩa là Tôi đi mua sách.", "Remove ます and use に before a movement verb to express the purpose. 本を買いに行きます。 means I am going to buy a book.", "Có thể thêm địa điểm đích, như 図書館へ勉強しに行きます.", "A destination can also be included, as in 図書館へ勉強しに行きます."),
        (35, "plain-forms", "普通形と丁寧形", "普通形／丁寧形", "Dạng ngắn và dạng lịch sự", "Plain and polite forms", "Dạng ngắn gồm khẳng định và phủ định ở hiện tại/phi quá khứ và quá khứ. Với 食べる, bốn dạng là 食べる, 食べない, 食べた và 食べなかった. Dạng lịch sự tương ứng dùng ます hoặc です tùy từ loại.", "Plain forms include affirmative and negative non-past and past forms. 食べる has 食べる, 食べない, 食べた and 食べなかった. Corresponding polite forms use ます or です according to the word class.", "Danh từ và tính từ な dùng だ trong dạng ngắn khẳng định phi quá khứ cuối câu. Lựa chọn cách nói phụ thuộc quan hệ và tình huống.", "Nouns and na-adjectives use だ in the plain affirmative non-past sentence ending. Choose the register to suit the relationship and situation."),
    ];

